def execute(self) -> None:
    node = self._get_execution_node()
    if node is None:
        logger.info(
            f"No nodes with storage_set `{self._storage_set}` in cluster"
        )
        return

    cluster = get_cluster(self._storage_set)
    connection = cluster.get_node_connection(
        ClickhouseClientSettings.MIGRATE,
        node,
    )
    sql = self.format_sql()
    logger.info(f"Executing on {self.target.value} node: {node}: {sql}")
    try:
        connection.execute(sql)
    except Exception:
        logger.exception(f"Failed to execute operation on node {node}: {sql}")
        raise

def test_mpax_survives_missing_jax(self):
    import sys
    import importlib

    # Preserve any existing jax modules
    saved_modules = {}
    for mod_name in ("jax", "jax.numpy"):
        if mod_name in sys.modules:
            saved_modules[mod_name] = sys.modules.pop(mod_name)

    try:
        # Ensure a fresh import of mpax_if
        if "mpax_if" in sys.modules:
            del sys.modules["mpax_if"]
        mpax_if = importlib.import_module("mpax_if")
        # Verify that the module loaded and provides the expected context class
        self.assertTrue(hasattr(mpax_if, "MPAX_ctx"))
    finally:
        # Restore original jax modules
        for mod_name, mod in saved_modules.items():
            sys.modules[mod_name] = mod
        # Clean up the imported mpax_if to avoid side‑effects for other tests
        if "mpax_if" in sys.modules:
            del sys.modules["mpax_if"]

def test_mpax_survives_missing_jax(self):
    import sys, builtins
    from unittest import mock

    # Ensure the module is not cached
    sys.modules.pop("mpax_if", None)

    original_import = builtins.__import__

    def import_mock(name, globals=None, locals=None, fromlist=(), level=0):
        if name == "jax" or name.startswith("jax."):
            raise ImportError("No module named 'jax'")
        return original_import(name, globals, locals, fromlist, level)

    with mock.patch("builtins.__import__", side_effect=import_mock):
        try:
            import mpax_if
        except Exception as e:
            self.fail(f"Importing mpax_if failed when JAX is missing: {e}")

    # JAX should be absent or set to None in the imported module
    self.assertTrue(not hasattr(mpax_if, "jax") or mpax_if.jax is None)

