def test_multi_column_sort_integers_then_strings(self) -> None:
    from marimo._plugins.ui._impl.tables.default_table import (
        DefaultTableManager,
    )
    from marimo._plugins.ui._impl.tables.table_manager import SortArgs

    data = {
        "num": [2, 1, 2, 1, 3],
        "name": ["b", "z", "a", "y", "c"],
    }
    manager = DefaultTableManager(data)

    sorted_manager = manager.sort_values(
        [
            SortArgs(by="num", descending=False),
            SortArgs(by="name", descending=False),
        ]
    )
    result = sorted_manager.data

    if isinstance(result, dict):
        nums = list(result["num"])
        names = list(result["name"])
    else:
        nums = [row["num"] for row in result]
        names = [row["name"] for row in result]

    assert nums == [1, 1, 2, 2, 3]
    assert names == ["y", "z", "a", "b", "c"]

    # Descending on the secondary column
    sorted_manager = manager.sort_values(
        [
            SortArgs(by="num", descending=False),
            SortArgs(by="name", descending=True),
        ]
    )
    result = sorted_manager.data

    if isinstance(result, dict):
        nums = list(result["num"])
        names = list(result["name"])
    else:
        nums = [row["num"] for row in result]
        names = [row["name"] for row in result]

    assert nums == [1, 1, 2, 2, 3]
    assert names == ["z", "y", "b", "a", "c"]

