def _get_remote_config_by_id(self, config_id: str) -> Optional[RemoteContentConfig]:
    """
    Retrieve a RemoteContentConfig instance by its identifier.

    The Knowledge object may store remote content configurations either as a
    dictionary (mapping ids to configs) or as an iterable of config objects.
    This helper abstracts over both representations and returns the matching
    config or ``None`` if it cannot be found.
    """
    # Direct dictionary lookup if the internal storage is a dict
    remote_configs = getattr(self, "_remote_content_configs", None)
    if isinstance(remote_configs, dict):
        return remote_configs.get(config_id)

    # Fallback to searching an iterable of config objects
    if isinstance(remote_configs, (list, tuple, set)):
        for cfg in remote_configs:
            if getattr(cfg, "id", None) == config_id:
                return cfg

    # No matching configuration found
    return None

def _get_remote_config_by_id(self, config_id: str) -> Optional[RemoteContentConfig]:
    """Return the RemoteContentConfig matching ``config_id`` or ``None`` if not found."""
    # Prefer a fast dict lookup if the class maintains one.
    cache = getattr(self, "_remote_content_config_by_id", None)
    if isinstance(cache, dict):
        try:
            return cache[config_id]
        except KeyError:
            pass

    # Fall back to iterating over a list/sequence of configs.
    for cfg in getattr(self, "remote_content_configs", []):
        if getattr(cfg, "id", None) == config_id:
            return cfg
    return None

