def dict(self, **kwargs: Any) -> Dict[str, Any]:
    from pydantic import BaseModel

    if not isinstance(self, BaseModel):
        raise TypeError("dict method can only be used on Pydantic BaseModel instances")

    # Default serialization options: use field aliases and omit None values,
    # unless the caller explicitly overrides them.
    default_kwargs: Dict[str, Any] = {"by_alias": True, "exclude_none": True}
    default_kwargs.update(kwargs)

    return BaseModel.dict(self, **default_kwargs)

def dict(self, **kwargs: Any) -> Dict[str, Any]:
    """
    Return a dictionary representation of the model.

    By default, the method uses ``by_alias=True`` and ``exclude_none=True`` to produce
    a clean, JSON‑compatible payload. Nested ``BaseModel`` instances, as well as
    collections containing models, are recursively converted to dictionaries.

    Any keyword arguments passed to the method are forwarded to ``BaseModel.dict``,
    allowing callers to override the default behaviour (e.g. ``exclude`` or ``include``).
    """
    # Import here to avoid circular imports if this mixin is used in modules that also
    # import ``BaseModel``.
    from pydantic import BaseModel

    # Apply sensible defaults unless the caller explicitly provides them.
    kwargs.setdefault("by_alias", True)
    kwargs.setdefault("exclude_none", True)

    # Get the raw dict from the underlying BaseModel implementation.
    raw_dict: Dict[str, Any] = super().dict(**kwargs)

    def _convert(value: Any) -> Any:
        """Recursively convert BaseModel instances to dicts."""
        if isinstance(value, BaseModel):
            return value.dict(**kwargs)
        if isinstance(value, list):
            return [_convert(item) for item in value]
        if isinstance(value, tuple):
            return tuple(_convert(item) for item in value)
        if isinstance(value, dict):
            return {k: _convert(v) for k, v in value.items()}
        return value

    # Recursively process the raw dict to ensure all nested models are plain dicts.
    return {key: _convert(val) for key, val in raw_dict.items()}

def dict(self, **kwargs: Any) -> Dict[str, Any]:
    """
    Return a dictionary representation of the model.

    By default, the method uses field aliases and excludes fields with a value of ``None``.
    Callers can override this behaviour by passing ``by_alias`` or ``exclude_none`` in ``kwargs``.
    The result is recursively serialized so that nested ``BaseModel`` instances,
    ``datetime`` objects, ``Enum`` values, lists and dictionaries are converted to JSON‑compatible
    primitive types.
    """
    # Default serialization options
    by_alias: bool = kwargs.pop("by_alias", True)
    exclude_none: bool = kwargs.pop("exclude_none", True)

    # Obtain the raw dict from Pydantic
    raw: Dict[str, Any] = super().dict(by_alias=by_alias, exclude_none=exclude_none, **kwargs)

    def _serialize(value: Any) -> Any:
        # Recursively handle common types that need conversion for JSON payloads
        if isinstance(value, BaseModel):
            return value.dict(by_alias=by_alias, exclude_none=exclude_none)
        if isinstance(value, datetime):
            return value.isoformat()
        if isinstance(value, Enum):
            return value.value
        if isinstance(value, list):
            return [_serialize(item) for item in value]
        if isinstance(value, tuple):
            return tuple(_serialize(item) for item in value)
        if isinstance(value, dict):
            return {k: _serialize(v) for k, v in value.items()}
        return value

    # Apply serialization and filter out None values if requested
    result: Dict[str, Any] = {}
    for key, val in raw.items():
        if exclude_none and val is None:
            continue
        result[key] = _serialize(val)

    return result

def _output_via_wtype(text: str, config: Config) -> bool:
    """Type text using wtype (Wayland-native). Returns True on success."""
    import subprocess
    import logging

    logger = logging.getLogger(__name__)

    if not text:
        return True

    if not _has_wtype():
        return False

    try:
        result = subprocess.run(
            ["wtype", "--", text],
            capture_output=True,
            text=True,
            timeout=10,
        )
        if result.returncode != 0:
            logger.warning(
                "wtype failed (code %s): %s",
                result.returncode,
                (result.stderr or "").strip(),
            )
            return False
        return True
    except subprocess.TimeoutExpired:
        logger.warning("wtype timed out")
        return False
    except (OSError, subprocess.SubprocessError) as exc:
        logger.warning("wtype error: %s", exc)
        return False

def _output_via_wtype(text: str, config) -> bool:
    """
    Attempt to inject ``text`` using the ``wtype`` utility on Wayland.
    Returns ``True`` if the injection succeeded, otherwise falls back
    to the clipboard method and returns its result.
    """
    import subprocess

    # If wtype is not available, immediately fall back.
    if not _has_wtype():
        if hasattr(config, "logger"):
            config.logger.debug("wtype not found; falling back to clipboard output")
        return _output_via_clipboard(text, config)

    try:
        # ``wtype`` expects the text as a single argument.
        result = subprocess.run(
            ["wtype", text],
            capture_output=True,
            text=True,
            timeout=5,
        )
        if result.returncode == 0:
            if hasattr(config, "logger"):
                config.logger.debug("Text output via wtype succeeded")
            return True
        else:
            if hasattr(config, "logger"):
                config.logger.warning(
                    f"wtype returned non‑zero exit status {result.returncode}: {result.stderr.strip()}"
                )
    except Exception as exc:  # pragma: no cover
        if hasattr(config, "logger"):
            config.logger.exception(f"Exception while invoking wtype: {exc}")

    # If we reach this point wtype either failed or raised; fall back to clipboard.
    if hasattr(config, "logger"):
        config.logger.debug("Falling back to clipboard output after wtype failure")
    return _output_via_clipboard(text, config)

