def __hash__(self):
    """Returns a hash of the geometry descriptor based on its shape and offset."""
    shape_hash = hash(self.shape) if self.shape is not None else 0
    offset = self.offset
    try:
        offset_key = tuple(float(x) for x in offset)
    except TypeError:
        offset_key = (id(offset),)
    return hash((self.name, shape_hash, offset_key))
