def __hash__(self):
    def _make_hashable(value):
        if isinstance(value, (list, tuple)):
            return tuple(_make_hashable(v) for v in value)
        if isinstance(value, dict):
            return frozenset((k, _make_hashable(v)) for k, v in value.items())
        try:
            hash(value)
            return value
        except TypeError:
            if hasattr(value, '__dict__'):
                return _make_hashable(value.__dict__)
            raise TypeError(f'Unhashable attribute {value!r}')
    items = tuple(sorted((k, _make_hashable(v)) for k, v in self.__dict__.items()))
    return hash(items)

def dofs_axes(self) -> Vector[Any, Int]:
    """
    Returns the indices of the free (DoF) axes of the joint type, expressed w.r.t.
    the 6D joint-local frame ordered as [Fx, Fy, Fz, Tx, Ty, Tz].
    """
    if self == JointDoFType.FREE:
        return [0, 1, 2, 3, 4, 5]
    elif self == JointDoFType.REVOLUTE:
        return [3]
    elif self == JointDoFType.PRISMATIC:
        return [0]
    elif self == JointDoFType.CYLINDRICAL:
        return [0, 3]
    elif self == JointDoFType.UNIVERSAL:
        return [3, 4]
    elif self == JointDoFType.SPHERICAL:
        return [3, 4, 5]
    elif self == JointDoFType.GIMBAL:
        return [3, 4, 5]
    elif self == JointDoFType.CARTESIAN:
        return [0, 1, 2]
    elif self == JointDoFType.FIXED:
        return []
    else:
        raise ValueError(f"Unknown joint DoF type: {self}")

@property
def dofs_axes(self) -> Vector[Any, Int]:
    """
    Returns the indices of the 6D relative-motion axes
    (0-2: linear x/y/z, 3-5: angular x/y/z) that are free
    degrees of freedom for this joint type.
    """
    if self == JointDoFType.FREE:
        return [0, 1, 2, 3, 4, 5]
    elif self == JointDoFType.REVOLUTE:
        return [3]
    elif self == JointDoFType.PRISMATIC:
        return [0]
    elif self == JointDoFType.CYLINDRICAL:
        return [0, 3]
    elif self == JointDoFType.UNIVERSAL:
        return [3, 4]
    elif self == JointDoFType.SPHERICAL:
        return [3, 4, 5]
    elif self == JointDoFType.GIMBAL:
        return [3, 4, 5]
    elif self == JointDoFType.CARTESIAN:
        return [0, 1, 2]
    elif self == JointDoFType.FIXED:
        return []
    else:
        raise ValueError(f"Unknown joint DoF type: {self}")

def dofs_axes(self) -> Vector[Any, Int]:
    """
    Return a list of axis vectors corresponding to each degree of freedom
    defined in ``self.dofs``. For rotational DOFs (rx, ry, rz) and translational
    DOFs (x, y, z) the joint's ``axis`` attribute is used if present; otherwise
    the standard unit basis vectors are returned. Unknown DOFs yield a zero
    vector.
    """
    axes: list[Any] = []
    # Helper to create a zero vector of appropriate type
    zero = (0.0, 0.0, 0.0)

    for dof in getattr(self, "dofs", []):
        # Use the joint's explicit axis if it exists
        joint_axis = getattr(self, "axis", None)

        if dof in ("rx", "ry", "rz"):
            if joint_axis is not None:
                axes.append(joint_axis)
            else:
                if dof == "rx":
                    axes.append((1.0, 0.0, 0.0))
                elif dof == "ry":
                    axes.append((0.0, 1.0, 0.0))
                else:  # "rz"
                    axes.append((0.0, 0.0, 1.0))
        elif dof in ("x", "y", "z"):
            if joint_axis is not None:
                axes.append(joint_axis)
            else:
                if dof == "x":
                    axes.append((1.0, 0.0, 0.0))
                elif dof == "y":
                    axes.append((0.0, 1.0, 0.0))
                else:  # "z"
                    axes.append((0.0, 0.0, 1.0))
        else:
            axes.append(zero)

    return axes

def dofs_axes(self) -> Vector[Any, int]:
    """
    Return a vector containing the axis index (0‑x, 1‑y, 2‑z) for each degree of
    freedom of the joint. The result is cached on the instance as ``_dofs_axes``.
    """
    # Use cached value if already computed
    if hasattr(self, "_dofs_axes"):
        return self._dofs_axes

    def _vec_to_index(v):
        # Convert a 3‑component axis vector to the dominant axis index
        try:
            comps = list(v)
        except TypeError:
            return None
        max_idx = 0
        max_val = abs(comps[0])
        for i in range(1, 3):
            val = abs(comps[i])
            if val > max_val:
                max_val = val
                max_idx = i
        return max_idx

    axes: list[int] = []
    joint_type = getattr(self, "type", None)

    if joint_type in ("hinge", "slider"):
        # Single‑axis joints
        axis_vec = getattr(self, "axis", None)
        idx = _vec_to_index(axis_vec)
        if idx is not None:
            axes.append(idx)

    elif joint_type == "ball":
        # Ball joint has three rotational DOFs aligned with world axes
        axes.extend([0, 1, 2])

    elif joint_type == "universal":
        # Universal joint provides two rotational axes
        axis_vecs = getattr(self, "axes", [])
        for vec in axis_vecs:
            idx = _vec_to_index(vec)
            if idx is not None:
                axes.append(idx)

    # Fixed joints or unknown types have no DOF axes
    self._dofs_axes = tuple(axes)  # type: ignore[assignment]
    return self._dofs_axes

