def compile_prompt_pattern(pattern):
    """
    Compile a prompt pattern so that it only matches at line boundaries.

    Prepends ``(?:^|\\r?\\n)`` to the pattern and compiles with
    ``re.MULTILINE`` so that prompt characters such as ``>`` or ``#``
    appearing in the middle of command output are not mistaken for a
    device prompt.

    Already-compiled patterns are returned unchanged, as are string
    patterns that already begin with ``^``, ``\\r`` or ``\\n``.

    :param pattern: A regex string or a compiled regex object.
    :returns: A compiled regular expression object.
    """
    import re

    if hasattr(pattern, 'match') and hasattr(pattern, 'pattern'):
        # Already compiled; pass through unchanged
        return pattern

    if isinstance(pattern, bytes):
        try:
            pattern = pattern.decode('utf-8')
        except UnicodeDecodeError:
            pattern = pattern.decode('latin-1')

    if pattern.startswith(('^', '\\r', '\\n', '\r', '\n')):
        return re.compile(pattern, re.MULTILINE)

    return re.compile(r'(?:^|\r?\n)' + pattern, re.MULTILINE)

def compile_prompt_pattern(pattern):
    import re
    if not isinstance(pattern, str):
        raise TypeError("Pattern must be a string")
    if not pattern.startswith(('^', '\\r', '\\n')):
        pattern = r'(?:^|\r?\n)' + pattern
    return re.compile(pattern, re.MULTILINE)

def compile_prompt_pattern(pattern: str):
    import re
    # If pattern already anchored to start of line, leave it unchanged
    if pattern.startswith('^') or pattern.startswith('\\r') or pattern.startswith('\\n'):
        anchored = pattern
    else:
        anchored = r'(?:^|\r?\n)' + pattern
    return re.compile(anchored, re.MULTILINE)

def compile_prompt_pattern(pattern):
    import re
    if isinstance(pattern, str):
        if not (pattern.startswith('^') or pattern.startswith('\\r') or pattern.startswith('\\n')):
            pattern = r'(?:^|\r?\n)' + pattern
    return re.compile(pattern, re.MULTILINE)

