async def _get_session_id_for_element(self, element_node: EnhancedDOMTreeNode) -> str | None:
    """Return the CDP session id that should be used to interact with the given element.

    Elements inside out-of-process iframes live in a different target than the
    main page, so we look up the session bound to the element's frame. Falls back
    to the currently focused session when the frame cannot be resolved.
    """
    if element_node is None:
        return None

    frame_id = getattr(element_node, 'frame_id', None)
    if frame_id:
        try:
            cdp_session = await self.browser_session.get_cdp_session_for_frame(frame_id)
            if cdp_session is not None:
                return cdp_session.session_id
        except Exception:
            pass

    session_id = getattr(element_node, 'session_id', None)
    if session_id:
        return session_id

    focused = getattr(self.browser_session, 'agent_focus', None)
    if focused is not None:
        return getattr(focused, 'session_id', None)

    return None
