def _boundary_values(boundaries, min_val, max_val, step=1, width=5, sparse_count=100):
    values = set()
    is_int = all(isinstance(x, int) for x in (min_val, max_val, step, *boundaries))

    for b in boundaries:
        for k in range(-width, width + 1):
            v = b + k * step
            if min_val <= v <= max_val:
                values.add(v)

    values.add(min_val)
    values.add(max_val)

    if sparse_count > 1:
        span = max_val - min_val
        for i in range(sparse_count):
            if is_int:
                values.add(min_val + (span * i) // (sparse_count - 1))
            else:
                values.add(min_val + span * i / (sparse_count - 1))

    return sorted(values)
