def _boundary_values(boundaries, min_val, max_val, step=1, width=5, sparse_count=100):
    values = set()
    for b in boundaries:
        for k in range(-width, width + 1):
            v = b + k * step
            if min_val <= v <= max_val:
                values.add(v)
    if sparse_count > 0 and max_val > min_val:
        if sparse_count == 1:
            values.add(min_val)
        else:
            for i in range(sparse_count):
                v = min_val + (max_val - min_val) * i / (sparse_count - 1)
                v = min_val + round((v - min_val) / step) * step
                if min_val <= v <= max_val:
                    values.add(v)
    return sorted(values)

def _boundary_values(boundaries, min_val, max_val, step=1, width=5, sparse_count=100):
  """Generate test values concentrated around boundaries plus sparse sampling.

  boundaries: iterable of threshold values
  min_val, max_val: inclusive range of values
  step: spacing between values (int or float)
  width: number of steps to include on each side of each boundary
  sparse_count: approximate number of evenly spaced values across the full range
  """
  values = set()

  def _add(v):
    if min_val <= v <= max_val:
      values.add(v)

  # range endpoints
  _add(min_val)
  _add(max_val)

  # values around each boundary
  for b in boundaries:
    for i in range(-width, width + 1):
      v = b + i * step
      if isinstance(step, float) or isinstance(b, float) or isinstance(min_val, float):
        v = round(v, 10)
      _add(v)

  # sparse sampling across the full range
  if sparse_count and sparse_count > 0 and max_val >= min_val:
    n_steps = int(round((max_val - min_val) / step))
    if n_steps > 0:
      stride = max(1, n_steps // sparse_count)
      for i in range(0, n_steps + 1, stride):
        v = min_val + i * step
        if isinstance(step, float) or isinstance(min_val, float):
          v = round(v, 10)
        _add(v)

  return sorted(values)

