def _find_def_line(self, lines: List[str], function_name: str) -> Optional[int]:
    """Return the index of the line containing 'def <function_name>(', or None if not found."""
    for index, line in enumerate(lines):
        stripped = line.lstrip()
        if not stripped.startswith("def "):
            continue
        rest = stripped[4:].lstrip()
        if rest.startswith(function_name) and rest[len(function_name):].lstrip().startswith("("):
            return index
    return None
