def _find_def_line(self, lines: List[str], function_name: str) -> Optional[int]:
    """Find the line index of the function definition for the given function name.

    Handles plain and async definitions, and definitions whose signature
    spans multiple lines. Returns None if the function is not found.
    """
    import re

    pattern = re.compile(
        r"^\s*(?:async\s+)?def\s+" + re.escape(function_name) + r"\s*\("
    )
    for index, line in enumerate(lines):
        if pattern.match(line):
            return index
    return None

