def wait_for_learning(self, timeout: Optional[float] = None) -> bool:
    """Wait for background learning to finish.

    Args:
        timeout: Maximum seconds to wait. None waits indefinitely.

    Returns:
        True if all learning completed (or nothing was pending),
        False if the timeout expired first.
    """
    import time

    pipeline = getattr(self, "_pipeline", None)
    if pipeline is not None and hasattr(pipeline, "wait_for_completion"):
        try:
            return bool(pipeline.wait_for_completion(timeout))
        except Exception:
            return False

    thread = getattr(self, "_learning_thread", None)
    if thread is not None:
        if thread.is_alive():
            thread.join(timeout)
        return not thread.is_alive()

    threads = list(getattr(self, "_learning_threads", []) or [])
    if not threads:
        return True

    deadline = None if timeout is None else time.monotonic() + timeout
    for t in threads:
        if not t.is_alive():
            continue
        remaining = None if deadline is None else max(0.0, deadline - time.monotonic())
        t.join(remaining)
        if t.is_alive():
            return False
    return True

def wait_for_learning(self, timeout: Optional[float] = None) -> bool:
    """Wait for background learning to complete.

    Args:
        timeout: Maximum seconds to wait. None waits indefinitely.

    Returns:
        True if learning finished (or nothing was pending), False if the
        timeout expired first.
    """
    import time

    start = time.time()

    # Delegate to the underlying async learning pipeline if one is configured
    pipeline = getattr(self, "_adapter", None) or getattr(self, "_runner", None)
    if pipeline is not None and hasattr(pipeline, "wait_for_learning"):
        try:
            return bool(pipeline.wait_for_learning(timeout))
        except Exception:
            return False

    # Fall back to joining any background learning thread
    thread = getattr(self, "_learning_thread", None)
    if thread is not None and thread.is_alive():
        remaining = None
        if timeout is not None:
            remaining = max(0.0, timeout - (time.time() - start))
        thread.join(remaining)
        return not thread.is_alive()

    return True

def wait_for_learning(self, timeout: Optional[float] = None) -> bool:
    """Wait for background learning to complete.

    Args:
        timeout: Maximum seconds to wait. None waits indefinitely.

    Returns:
        True if all learning has finished (or none was pending),
        False if the timeout expired first.
    """
    import time

    start = time.monotonic()

    # Prefer the pipeline's own background-wait if it exists
    pipeline = getattr(self, "_pipeline", None)
    if pipeline is not None and hasattr(pipeline, "wait_for_background"):
        try:
            result = pipeline.wait_for_background(timeout=timeout)
            return True if result is None else bool(result)
        except TypeError:
            result = pipeline.wait_for_background(timeout)
            return True if result is None else bool(result)

    # Fall back to joining any tracked learning threads
    threads = []
    single = getattr(self, "_learning_thread", None)
    if single is not None:
        threads.append(single)
    threads.extend(getattr(self, "_learning_threads", []) or [])

    for thread in threads:
        if thread is None or not thread.is_alive():
            continue
        remaining = None
        if timeout is not None:
            remaining = timeout - (time.monotonic() - start)
            if remaining <= 0:
                return False
        thread.join(remaining)
        if thread.is_alive():
            return False

    return True

