def wait_for_learning(self, timeout: Optional[float] = None) -> bool:
    """
    Waits until the learning loop produces at least one new commit.

    Returns:
        bool: True if a new commit was observed before the timeout,
              False if the timeout elapsed without progress.
    """
    import time

    start_time = time.time()
    poll_interval = getattr(self, "poll_interval", 1.0)

    # Capture the initial commit count; subclasses should provide this method.
    try:
        initial_count = self.get_commit_count()
    except Exception as e:
        if hasattr(self, "logger"):
            self.logger.error(f"Failed to obtain initial commit count: {e}")
        return False

    while True:
        # Check for timeout
        if timeout is not None and (time.time() - start_time) >= timeout:
            if hasattr(self, "logger"):
                self.logger.warning("wait_for_learning timed out without detecting new commits.")
            return False

        time.sleep(poll_interval)

        try:
            current_count = self.get_commit_count()
        except Exception as e:
            if hasattr(self, "logger"):
                self.logger.error(f"Failed to obtain current commit count: {e}")
            continue  # keep trying until timeout

        if current_count > initial_count:
            if hasattr(self, "logger"):
                self.logger.info(
                    f"Learning progress detected: commit count increased from {initial_count} to {current_count}."
                )
            return True

        # Optional stall detection: if count hasn't changed for a prolonged period,
        # we could break early. This implementation relies solely on the timeout.

def grep_count_files(name: str, file_list: list[str], *, pattern: str, flags: int = 0) -> int:
    """Count files in file_list that contain at least one line matching pattern.

    name is a label for the check, used for reporting.
    """
    regex = re.compile(pattern, flags)
    count = 0
    for filepath in file_list:
        try:
            with open(filepath, encoding="utf-8", errors="ignore") as f:
                for line in f:
                    if regex.search(line):
                        count += 1
                        break
        except OSError:
            continue
    return count

