def grep_count_files(name: str, file_list: list[str], *,
                    word_boundary: bool = True,
                    case_sensitive: bool = True) -> int:
    """Count how many files in file_list contain a reference to `name`.

    Pure-Python replacement for `grep -rl name | wc -l`. Each file is counted
    at most once. Unreadable files are skipped.
    """
    if not name or not file_list:
        return 0

    pattern_text = re.escape(name)
    if word_boundary:
        pattern_text = r"\b" + pattern_text + r"\b"
    flags = 0 if case_sensitive else re.IGNORECASE
    pattern = re.compile(pattern_text, flags)

    count = 0
    for filepath in file_list:
        path = filepath
        if not os.path.isabs(path):
            try:
                path = os.path.join(str(PROJECT_ROOT), filepath)
            except NameError:
                path = filepath
        try:
            with open(path, encoding="utf-8", errors="replace") as f:
                for line in f:
                    if pattern.search(line):
                        count += 1
                        break
        except (OSError, UnicodeDecodeError):
            continue
    return count

def _extract_tree(module, name=""):
    import torch.nn as nn

    uninit_cls = getattr(nn.parameter, "UninitializedParameter", None)
    lazy_mixin = getattr(getattr(nn, "modules", None) and nn.modules.lazy, "LazyModuleMixin", None)
    seen = {}

    def _is_lazy_param(p):
        return uninit_cls is not None and isinstance(p, uninit_cls)

    def _walk(mod, nm):
        params = []
        for pname, p in mod.named_parameters(recurse=False):
            pid = id(p)
            shared = pid in seen
            if not shared:
                seen[pid] = f"{nm}.{pname}" if nm else pname
            lazy = _is_lazy_param(p)
            if lazy:
                shape = None
                numel = 0
                size_bytes = 0
            else:
                shape = tuple(p.shape)
                numel = int(p.numel())
                size_bytes = numel * p.element_size()
            params.append({
                "name": pname,
                "shape": shape,
                "numel": numel,
                "size_bytes": size_bytes,
                "trainable": bool(p.requires_grad),
                "shared": shared,
                "shared_with": seen[pid] if shared else None,
                "counted": not shared,
                "lazy": lazy,
            })

        warnings = []
        for attr, val in vars(mod).items():
            if attr.startswith("_"):
                continue
            if isinstance(val, (list, tuple)):
                items = list(val)
            elif isinstance(val, dict):
                items = list(val.values())
            else:
                continue
            if any(isinstance(x, nn.Module) for x in items):
                warnings.append(
                    f"'{attr}' holds nn.Module(s) in a plain "
                    f"{type(val).__name__}; use nn.ModuleList/nn.ModuleDict"
                )

        children = []
        for cname, child in mod.named_children():
            child_name = f"{nm}.{cname}" if nm else cname
            children.append(_walk(child, child_name))

        is_lazy_module = lazy_mixin is not None and isinstance(mod, lazy_mixin)
        return {
            "name": nm,
            "type": type(mod).__name__,
            "params": params,
            "children": children,
            "warnings": warnings,
            "lazy": is_lazy_module or any(p["lazy"] for p in params),
            "total_numel": sum(p["numel"] for p in params if p["counted"])
                + sum(c["total_numel"] for c in children),
            "total_size_bytes": sum(p["size_bytes"] for p in params if p["counted"])
                + sum(c["total_size_bytes"] for c in children),
        }

    return _walk(module, name)

