def _extract_tree(module, name=""):
    import torch.nn as nn
    from torch.nn.parameter import UninitializedParameter

    seen = {}

    def build(mod, node_name):
        params = []
        for pname, p in mod.named_parameters(recurse=False):
            uninit = isinstance(p, UninitializedParameter)
            key = id(p)
            shared_with = seen.get(key)
            counted = shared_with is None
            if counted:
                seen[key] = f"{node_name}.{pname}" if node_name else pname
            numel = 0 if uninit else p.numel()
            size = 0 if uninit else numel * p.element_size()
            params.append({
                "name": pname,
                "shape": None if uninit else tuple(p.shape),
                "uninitialized": uninit,
                "trainable": bool(p.requires_grad),
                "numel": numel if counted else 0,
                "size_bytes": size if counted else 0,
                "shared_with": shared_with,
                "counted": counted,
            })

        children = []
        for cname, child in mod._modules.items():
            if child is None:
                continue
            child_path = f"{node_name}.{cname}" if node_name else cname
            children.append(build(child, child_path))

        unregistered = []
        for attr, val in vars(mod).items():
            if attr.startswith("_") or attr in mod._modules:
                continue
            if isinstance(val, (list, tuple)) and any(isinstance(v, nn.Module) for v in val):
                unregistered.append(attr)
            elif isinstance(val, dict) and any(isinstance(v, nn.Module) for v in val.values()):
                unregistered.append(attr)

        lazy = any(p["uninitialized"] for p in params)
        if hasattr(mod, "has_uninitialized_params"):
            try:
                lazy = lazy or bool(mod.has_uninitialized_params())
            except Exception:
                pass

        shared = any(p["shared_with"] is not None for p in params)

        total_params = sum(p["numel"] for p in params) + sum(c["total_params"] for c in children)
        total_trainable = sum(p["numel"] for p in params if p["trainable"]) + sum(
            c["total_trainable"] for c in children
        )
        total_bytes = sum(p["size_bytes"] for p in params) + sum(c["total_bytes"] for c in children)

        badges = []
        if shared:
            badges.append("shared")
        if lazy:
            badges.append("lazy")

        warnings = []
        for attr in unregistered:
            warnings.append(
                f"'{attr}' holds nn.Module instances in a plain container; use nn.ModuleList/nn.ModuleDict"
            )

        return {
            "name": node_name,
            "type": type(mod).__name__,
            "params": params,
            "children": children,
            "badges": badges,
            "warnings": warnings,
            "lazy": lazy,
            "shared": shared,
            "total_params": total_params,
            "total_trainable": total_trainable,
            "total_bytes": total_bytes,
        }

    return build(module, name)
