def _extract_tree(module, name=""):
    import torch.nn as nn

    seen_params = {}

    def build(mod, mod_name):
        cls_name = type(mod).__name__
        uninit_cls = nn.parameter.UninitializedParameter
        own_params = list(mod.named_parameters(recurse=False))
        is_uninit = any(isinstance(p, uninit_cls) for _, p in own_params)

        node = {
            "name": mod_name or cls_name,
            "type": cls_name,
            "params": [],
            "children": [],
            "badges": [],
            "warnings": [],
            "lazy": is_uninit or cls_name.startswith("Lazy"),
        }

        if node["lazy"]:
            node["badges"].append("lazy")

        for pname, p in own_params:
            full_name = f"{mod_name}.{pname}" if mod_name else pname
            uninitialized = isinstance(p, uninit_cls)
            entry = {
                "name": pname,
                "shape": None if uninitialized else tuple(p.shape),
                "numel": 0 if uninitialized else p.numel(),
                "size_bytes": 0 if uninitialized else p.numel() * p.element_size(),
                "trainable": bool(p.requires_grad),
                "uninitialized": uninitialized,
                "shared": False,
                "counted": True,
            }
            pid = id(p)
            if pid in seen_params:
                entry["shared"] = True
                entry["counted"] = False
                entry["shared_with"] = seen_params[pid]
                if "shared" not in node["badges"]:
                    node["badges"].append("shared")
            else:
                seen_params[pid] = full_name
            if uninitialized:
                entry["display"] = "uninitialized"
            node["params"].append(entry)

        for cname, child in mod._modules.items():
            if child is None:
                continue
            child_name = f"{mod_name}.{cname}" if mod_name else cname
            node["children"].append(build(child, cname))

        registered = set(mod._modules.keys())
        for attr, value in vars(mod).items():
            if attr.startswith("_") or attr in registered:
                continue
            container = None
            if isinstance(value, (list, tuple)):
                container = "list" if isinstance(value, list) else "tuple"
                items = value
            elif isinstance(value, dict):
                container = "dict"
                items = list(value.values())
            else:
                continue
            if any(isinstance(item, nn.Module) for item in items):
                msg = (
                    f"'{attr}' holds nn.Module instances in a plain Python {container}; "
                    "use nn.ModuleList/nn.ModuleDict so they are registered"
                )
                node["warnings"].append(msg)

        return node

    return build(module, name)
