def _extract_tree(module, name=""):
    import torch.nn as nn
    from torch.nn.parameter import UninitializedParameter, UninitializedBuffer

    seen_params = set()

    def _find_unregistered(mod):
        warnings = []
        for attr, value in vars(mod).items():
            if attr in ("_modules", "_parameters", "_buffers") or attr.startswith("__"):
                continue
            found = 0
            if isinstance(value, (list, tuple, set)):
                found = sum(isinstance(v, nn.Module) for v in value)
            elif isinstance(value, dict):
                found = sum(isinstance(v, nn.Module) for v in value.values())
            if found:
                container = type(value).__name__
                warnings.append(
                    f"'{attr}' is a plain {container} containing {found} nn.Module "
                    f"instance(s); use nn.ModuleList/nn.ModuleDict so they are registered"
                )
        return warnings

    def _walk(mod, mod_name):
        params = []
        own_count = 0
        own_trainable = 0
        own_bytes = 0

        for pname, p in mod._parameters.items():
            if p is None:
                continue
            lazy = isinstance(p, UninitializedParameter)
            shared = False
            if id(p) in seen_params:
                shared = True
            else:
                seen_params.add(id(p))

            if lazy:
                info = {
                    "name": pname,
                    "shape": None,
                    "numel": 0,
                    "dtype": None,
                    "requires_grad": bool(p.requires_grad),
                    "shared": shared,
                    "lazy": True,
                }
            else:
                numel = p.numel()
                info = {
                    "name": pname,
                    "shape": list(p.shape),
                    "numel": numel,
                    "dtype": str(p.dtype).replace("torch.", ""),
                    "requires_grad": bool(p.requires_grad),
                    "shared": shared,
                    "lazy": False,
                }
                if not shared:
                    own_count += numel
                    if p.requires_grad:
                        own_trainable += numel
                    own_bytes += numel * p.element_size()
            params.append(info)

        buffers = []
        for bname, b in mod._buffers.items():
            if b is None:
                continue
            if isinstance(b, UninitializedBuffer):
                buffers.append({"name": bname, "shape": None, "lazy": True})
            else:
                buffers.append(
                    {"name": bname, "shape": list(b.shape), "lazy": False}
                )

        children = []
        child_count = 0
        child_trainable = 0
        child_bytes = 0
        for cname, child in mod._modules.items():
            if child is None:
                continue
            node = _walk(child, cname)
            children.append(node)
            child_count += node["total_params"]
            child_trainable += node["total_trainable"]
            child_bytes += node["total_bytes"]

        return {
            "name": mod_name,
            "type": type(mod).__name__,
            "params": params,
            "buffers": buffers,
            "children": children,
            "warnings": _find_unregistered(mod),
            "own_params": own_count,
            "total_params": own_count + child_count,
            "total_trainable": own_trainable + child_trainable,
            "total_bytes": own_bytes + child_bytes,
        }

    return _walk(module, name)

def _extract_tree(module, name=""):
    import torch

    visited_params = {}

    def _is_lazy_uninitialized(mod):
        # PyTorch lazy modules expose `has_uninitialized_params` property
        return getattr(mod, "has_uninitialized_params", False)

    def _process_module(mod, prefix):
        node = {
            "name": prefix,
            "type": mod.__class__.__name__,
            "children": [],
            "params": [],
        }

        # Detect lazy modules that are still uninitialized
        if _is_lazy_uninitialized(mod):
            node.setdefault("badges", []).append(
                {"type": "lazy", "label": "uninitialized"}
            )

        # Parameters (non‑recursive)
        for pname, param in mod.named_parameters(recurse=False):
            param_id = id(param)
            shared = param_id in visited_params
            visited_params[param_id] = (pname, prefix)

            param_info = {
                "name": pname,
                "shape": tuple(param.shape),
                "numel": param.numel(),
                "requires_grad": param.requires_grad,
            }
            if shared:
                param_info["shared"] = True
            node["params"].append(param_info)

        # Registered sub‑modules
        for child_name, child_mod in mod.named_children():
            child_prefix = f"{prefix}.{child_name}" if prefix else child_name
            node["children"].append(_process_module(child_mod, child_prefix))

        # Detect unregistered modules stored in plain containers
        for attr_name, attr_val in vars(mod).items():
            # Direct module attribute not registered
            if isinstance(attr_val, torch.nn.Module) and attr_name not in mod._modules:
                warning_node = {
                    "name": f"{prefix}.{attr_name}" if prefix else attr_name,
                    "type": attr_val.__class__.__name__,
                    "warning": "module stored in plain attribute (use nn.ModuleList/nn.ModuleDict)",
                }
                node["children"].append(warning_node)

            # List / tuple containers
            if isinstance(attr_val, (list, tuple)):
                for idx, item in enumerate(attr_val):
                    if isinstance(item, torch.nn.Module):
                        warning_node = {
                            "name": f"{prefix}.{attr_name}[{idx}]" if prefix else f"{attr_name}[{idx}]",
                            "type": item.__class__.__name__,
                            "warning": "module stored in plain list/tuple (use nn.ModuleList)",
                        }
                        node["children"].append(warning_node)

            # Dict containers
            if isinstance(attr_val, dict):
                for key, item in attr_val.items():
                    if isinstance(item, torch.nn.Module):
                        warning_node = {
                            "name": f"{prefix}.{attr_name}[{key}]" if prefix else f"{attr_name}[{key}]",
                            "type": item.__class__.__name__,
                            "warning": "module stored in plain dict (use nn.ModuleDict)",
                        }
                        node["children"].append(warning_node)

        return node

    return _process_module(module, name)
